// GinServerOptions provides options for the Gin server.
type GinServerOptions struct {
	BaseURL      string
	Middlewares  []MiddlewareFunc
	ErrorHandler func(*gin.Context, error, int)
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router gin.IRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, GinServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router gin.IRouter, si ServerInterface, options GinServerOptions) {
	errorHandler := options.ErrorHandler
	if errorHandler == nil {
		errorHandler = func(c *gin.Context, err error, statusCode int) {
			c.JSON(statusCode, gin.H{"msg": err.Error()})
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandler:       errorHandler,
	}

	router.GET(options.BaseURL+"/theme/themes", wrapper.ListThemes)
	router.POST(options.BaseURL+"/theme/themes", wrapper.CreateTheme)
	router.DELETE(options.BaseURL+"/theme/themes/:themeId", wrapper.DeleteTheme)
	router.GET(options.BaseURL+"/theme/themes/:themeId", wrapper.GetTheme)
	router.PATCH(options.BaseURL+"/theme/themes/:themeId", wrapper.RenameTheme)
	router.GET(options.BaseURL+"/theme/themes/:themeId/versions", wrapper.ListThemeVersions)
	router.POST(options.BaseURL+"/theme/themes/:themeId/publish", wrapper.PublishTheme)
	router.POST(options.BaseURL+"/theme/themes/:themeId/rollback", wrapper.RollbackTheme)
	router.POST(options.BaseURL+"/theme/themes/:themeId/sessions", wrapper.CreateThemeSession)
	router.POST(options.BaseURL+"/theme-editor/draft", wrapper.OpenDraft)
	router.PUT(options.BaseURL+"/theme-editor/draft/settings", wrapper.SaveDraftSettings)
	router.GET(options.BaseURL+"/theme-editor/draft/documents/:kind/:key", wrapper.GetDraftDocument)
	router.PUT(options.BaseURL+"/theme-editor/draft/documents/:kind/:key", wrapper.SaveDraftDocument)
	router.POST(options.BaseURL+"/theme-editor/draft/pages", wrapper.CreateDraftPage)
	router.DELETE(options.BaseURL+"/theme-editor/draft/pages/:key", wrapper.DeleteDraftPage)
	router.POST(options.BaseURL+"/theme-editor/publish", wrapper.PublishDraft)
	router.POST(options.BaseURL+"/theme-editor/preview-sessions", wrapper.CreatePreviewSession)
	router.GET(options.BaseURL+"/storefront/v1/theme", wrapper.GetStorefrontTheme)
	router.GET(options.BaseURL+"/storefront/v1/theme/versions/:versionId/documents/:kind/:key", wrapper.GetStorefrontThemeDocument)
	router.GET(options.BaseURL+"/storefront/v1/theme/preview/documents/:kind/:key", wrapper.GetStorefrontPreviewDocument)
}

